CREATE    PROCEDURE [synapse_fo].[usp_Insert_inventlocation]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-06-06 15:02:31
	Description: Insert stored procedure for inventlocation from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[INVENTLOCATION]
	(
		[ActivityType_RU],
		[AllowLaborStandards],
		[AllowMarkingReservationRemoval],
		[AutoUpdateShipment],
		[BranchNumber],
		[CONSOLIDATESHIPATRTW],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CustAccount_BR],
		[CustAccount_HU],
		[CycleCountAllowPalletMove],
		[DataAreaId],
		[DataLakeModified_DateTime],
		[DecrementLoadLine],
		[DefaultContainerTypeCode],
		[DefaultFinalShipmentLocation],
		[DefaultKanbanFinishedGoodsLocation],
		[DefaultProductionFinishGoodsLocation],
		[DefaultProductionInputLocation],
		[DefaultQualityMaintenanceLocation],
		[DefaultReturnCreditOnlyLocation],
		[DefaultShipMaintenanceLoc],
		[DefaultSortingLocation],
		[DefaultStatusId],
		[EMPTYPALLETLOCATION],
		[EnableQualityManagement],
		--[FileName],
		[FSHStore],
		[HMIMDomesticLanguage],
		[HMIMExportLanguage],
		[InventCountingGroup_BR],
		[InventLocationId],
		[InventLocationIdGoodsInRoute_RU],
		[InventLocationIdQuarantine],
		[InventLocationIdReqMain],
		[InventLocationIdTransit],
		[InventLocationLevel],
		[InventLocationType],
		[InventProfileId_RU],
		[InventProfileType_RU],
		[InventSiteId],
		[InventUseDefaultProductionLocationForFormulaBOM],
		[ITMInventLocationIdGIT],
		[ITMInventLocationIdUnder],
		[LastProcessedChange_DateTime],
		[LoadReleaseReservationPolicy],
		--[LSN],
		[Manual],
		[MAXPICKINGROUTETIME],
		[MAXPICKINGROUTEVOLUME],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[Name],
		[NumberSequenceGroup_RU],
		[PARTITION],
		[PICKINGLINETIME],
		[PrintBOLBeforeShipConfirm],
		[ProdReserveOnlyWhse],
		[RAFPostingMethod],
		[RBODefaultInventProfileId_RU],
		[RBODefaultWMSLocationId],
		[RBODEFAULTWMSPALLETID],
		[RECID],
		[RECVERSION],
		[RejectOrderFulfillment],
		[ReleaseToWarehouseRule],
		[RemoveInventBlockingOnStatusChange],
		[ReqCalendarId],
		[ReqRefill],
		[ReserveAtLoadPost],
		[RetailInventNegFinancial],
		[RetailInventNegPhysical],
		[RetailWeightEx1],
		[RetailWMSLocationIdDefaultReturn],
		[RETAILWMSPALLETIDDEFAULTRETURN],
		--[SysRowId],
		--[SYSSHARINGDATAAREAID],
		[UniqueCheckDigits],
		[USEWMSORDERS],
		[VendAccount],
		[VendAccountCustom_RU],
		[WarehouseAutoReleaseReservation],
		[WHSEnabled],
		[WHSProdOrderBackflushMustUseReservedQty],
		[WHSRawMaterialPolicy],
		[WMSAisleNameActive],
		[WMSLevelFormat],
		[WMSLevelNameActive],
		[WMSlocationIdDefaultIssue],
		[WMSLocationIdDefaultReceipt],
		[WMSLocationIdGoodsInRoute_RU],
		[WMSPositionFormat],
		[WMSPositionNameActive],
		[WMSRackFormat],
		[WMSRackNameActive],
		[WorkProcessingPolicyName]
	)
	SELECT 
		stg.[ActivityType_RU],
		stg.[AllowLaborStandards],
		stg.[AllowMarkingReservationRemoval],
		stg.[AutoUpdateShipment],
		stg.[BranchNumber],
		stg.[CONSOLIDATESHIPATRTW],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CustAccount_BR],
		stg.[CustAccount_HU],
		stg.[CycleCountAllowPalletMove],
		stg.[DataAreaId],
		stg.[DataLakeModified_DateTime],
		stg.[DecrementLoadLine],
		stg.[DefaultContainerTypeCode],
		stg.[DefaultFinalShipmentLocation],
		stg.[DefaultKanbanFinishedGoodsLocation],
		stg.[DefaultProductionFinishGoodsLocation],
		stg.[DefaultProductionInputLocation],
		stg.[DefaultQualityMaintenanceLocation],
		stg.[DefaultReturnCreditOnlyLocation],
		stg.[DefaultShipMaintenanceLoc],
		stg.[DefaultSortingLocation],
		stg.[DefaultStatusId],
		stg.[EMPTYPALLETLOCATION],
		stg.[EnableQualityManagement],
		--stg.--[FileName],
		stg.[FSHStore],
		stg.[HMIMDomesticLanguage],
		stg.[HMIMExportLanguage],
		stg.[InventCountingGroup_BR],
		stg.[InventLocationId],
		stg.[InventLocationIdGoodsInRoute_RU],
		stg.[InventLocationIdQuarantine],
		stg.[InventLocationIdReqMain],
		stg.[InventLocationIdTransit],
		stg.[InventLocationLevel],
		stg.[InventLocationType],
		stg.[InventProfileId_RU],
		stg.[InventProfileType_RU],
		stg.[InventSiteId],
		stg.[InventUseDefaultProductionLocationForFormulaBOM],
		stg.[ITMInventLocationIdGIT],
		stg.[ITMInventLocationIdUnder],
		stg.[LastProcessedChange_DateTime],
		stg.[LoadReleaseReservationPolicy],
		--stg.--[LSN],
		stg.[Manual],
		stg.[MAXPICKINGROUTETIME],
		stg.[MAXPICKINGROUTEVOLUME],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[Name],
		stg.[NumberSequenceGroup_RU],
		stg.[PARTITION],
		stg.[PICKINGLINETIME],
		stg.[PrintBOLBeforeShipConfirm],
		stg.[ProdReserveOnlyWhse],
		stg.[RAFPostingMethod],
		stg.[RBODefaultInventProfileId_RU],
		stg.[RBODefaultWMSLocationId],
		stg.[RBODEFAULTWMSPALLETID],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RejectOrderFulfillment],
		stg.[ReleaseToWarehouseRule],
		stg.[RemoveInventBlockingOnStatusChange],
		stg.[ReqCalendarId],
		stg.[ReqRefill],
		stg.[ReserveAtLoadPost],
		stg.[RetailInventNegFinancial],
		stg.[RetailInventNegPhysical],
		stg.[RetailWeightEx1],
		stg.[RetailWMSLocationIdDefaultReturn],
		stg.[RETAILWMSPALLETIDDEFAULTRETURN],
		--stg.--[SysRowId],
		--stg.[SYSSHARINGDATAAREAID],
		stg.[UniqueCheckDigits],
		stg.[USEWMSORDERS],
		stg.[VendAccount],
		stg.[VendAccountCustom_RU],
		stg.[WarehouseAutoReleaseReservation],
		stg.[WHSEnabled],
		stg.[WHSProdOrderBackflushMustUseReservedQty],
		stg.[WHSRawMaterialPolicy],
		stg.[WMSAisleNameActive],
		stg.[WMSLevelFormat],
		stg.[WMSLevelNameActive],
		stg.[WMSlocationIdDefaultIssue],
		stg.[WMSLocationIdDefaultReceipt],
		stg.[WMSLocationIdGoodsInRoute_RU],
		stg.[WMSPositionFormat],
		stg.[WMSPositionNameActive],
		stg.[WMSRackFormat],
		stg.[WMSRackNameActive],
		stg.[WorkProcessingPolicyName]	
	FROM [staging_fo].[INVENTLOCATION] stg
		LEFT JOIN [synapse_fo].[INVENTLOCATION] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[InventLocationId] = tgt.[InventLocationId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
END
